\subsection{Definitions}
\begin{itemize}
\item Borel function
\begin{definition}
A function $f_B: (X; \mathcal{B}) \to (X; \mathcal{C}$) of
\PMlinkname{Borel spaces}{BorelSpace} is defined to be a \emph{Borel function} if the inverse image of every Borel set under $f_B ^{-1}$ is also a Borel set.
\end{definition}

\item Borel groupoid
\begin{definition}
Let $\grp$ be a groupoid and $\grp^{(2)}$ a subset of $\grp \times \grp$-- the set of its composable pairs.
A {\em Borel groupoid} is defined as a groupoid $\grp_B$ such that $\grp_B^{(2)}$ is a Borel set in the product structure on $\grp_B \times \grp_B$, and also such that the functions $ (x,y) \mapsto xy$ from $\grp_B^{(2)}$ to $\grp_B$, and $ x \mapsto x^{-1}$ from $\grp_B$ to $\grp_B$ are all
\PMlinkname{(measurable) Borel functions}{MeasurableFunctions} (ref. \cite{MRB2k6}).
\end{definition}
\end{itemize}

\subsubsection{Analytic Borel space}

$\grp_B$ becomes an \PMlinkname{analytic groupoid}{LocallyCompactGroupoids} if its Borel structure is
\PMlinkname{analytic}{Analytic}.

A Borel space $(X; \mathcal{B})$ is called \emph{analytic} if it is
countably separated, and also if it is the image of a Borel function from a standard
Borel space.


\begin{thebibliography}{9}
\bibitem{MRB2k6}
M.R. Buneci. 2006.,
\PMlinkexternal{Groupoid C*-Algebras.}{http://www.utgjiu.ro/math/mbuneci/preprint/p0024.pdf},
{\em Surveys in Mathematics and its Applications}, Volume 1, p.75 .

\end{thebibliography}
